// HasPlaidAccountLinks filters parents that have a matching PlaidAccountLinks using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to PlaidAccountLinks).
func (w plaidItemWhereR[Q]) HasPlaidAccountLinks(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(PlaidAccountLinks.NameExpr()),
		sm.Where(PlaidAccountLinks.Columns.PlaidItemID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// NULL-tolerant scan buffer for plaidItemScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type plaidItemPreloadBuf struct {
	ID              null.Val[uuid.UUID]
	AccessToken     null.Val[string]
	PlaidItemID     null.Val[string]
	InstitutionID   null.Val[string]
	InstitutionName null.Val[string]
	Cursor          null.Val[string]
	CreatedAt       null.Val[time.Time]
}

// plaidItemScanMapperNullable maps the preloaded plaidItem
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func plaidItemScanMapperNullable(prefix string) scan.Mapper[*PlaidItem] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*PlaidItem, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *plaidItemPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.ID }})
			case "access_token":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.AccessToken }})
			case "plaid_item_id":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.PlaidItemID }})
			case "institution_id":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.InstitutionID }})
			case "institution_name":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.InstitutionName }})
			case "cursor":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.Cursor }})
			case "created_at":
				targets = append(targets, target{i, func(b *plaidItemPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(plaidItemPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*PlaidItem, error) {
				buf := link.(*plaidItemPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.AccessToken.IsValue()) &&
					!(buf.PlaidItemID.IsValue()) &&
					!(buf.InstitutionID.IsValue()) &&
					!(buf.InstitutionName.IsValue()) &&
					!(buf.Cursor.IsValue()) &&
					!(buf.CreatedAt.IsValue()) {
					return nil, nil
				}

				o := new(PlaidItem)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.AccessToken.IsValue() {
					o.AccessToken = buf.AccessToken.MustGet()
				}
				if buf.PlaidItemID.IsValue() {
					o.PlaidItemID = buf.PlaidItemID.MustGet()
				}
				if buf.InstitutionID.IsValue() {
					o.InstitutionID = buf.InstitutionID.MustGet()
				}
				if buf.InstitutionName.IsValue() {
					o.InstitutionName = buf.InstitutionName.MustGet()
				}
				if buf.Cursor.IsValue() {
					o.Cursor = buf.Cursor.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *PlaidItem) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "PlaidAccountLinks":
		rels, ok := retrieved.(PlaidAccountLinkSlice)
		if !ok {
			return fmt.Errorf("plaidItem cannot load %T as %q", retrieved, name)
		}

		o.R.PlaidAccountLinks = rels
		o.R.Loaded.PlaidAccountLinks = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.PlaidItem = o
				rel.R.Loaded.PlaidItem = true
			}
		}
		return nil
	default:
		return fmt.Errorf("plaidItem has no relationship %q", name)
	}
}

