// LoadPlaidAccountLinks loads the plaidItem's PlaidAccountLinks into the .R struct
func (o *PlaidItem) LoadPlaidAccountLinks(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.PlaidAccountLinks = nil
	o.R.Loaded.PlaidAccountLinks = false

	related, err := o.PlaidAccountLinks(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.PlaidItem = o
		rel.R.Loaded.PlaidItem = true
	}

	o.R.PlaidAccountLinks = related
	o.R.Loaded.PlaidAccountLinks = true
	return nil
}

// LoadPlaidAccountLinks loads the plaidItem's PlaidAccountLinks into the .R struct
func (os PlaidItemSlice) LoadPlaidAccountLinks(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	plaidAccountLinks, err := os.PlaidAccountLinks(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.PlaidAccountLinks = nil
		o.R.Loaded.PlaidAccountLinks = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	plaidItemByKey := make(map[uuid.UUID][]*PlaidItem, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		plaidItemByKey[o.ID] = append(plaidItemByKey[o.ID], o)
	}

	for _, rel := range plaidAccountLinks {

		owners, ok := plaidItemByKey[rel.PlaidItemID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.PlaidItem = o
			rel.R.Loaded.PlaidItem = true

			o.R.PlaidAccountLinks = append(o.R.PlaidAccountLinks, rel)

		}
	}

	return nil
}

