type plaidItemCountPreloader struct {
	PlaidAccountLinks func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildPlaidItemCountPreloader() plaidItemCountPreloader {
	return plaidItemCountPreloader{
		PlaidAccountLinks: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*PlaidItem]("PlaidAccountLinks", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = PlaidItems.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(PlaidAccountLinks.NameAsExpr()),
					sm.Where(psql.Quote(PlaidAccountLinks.Alias(), "plaid_item_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

