// LoadCountPlaidAccountLinks loads the count of PlaidAccountLinks for a slice in a single batch query
func (os PlaidItemSlice) LoadCountPlaidAccountLinks(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "uuid[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			PlaidAccountLinks.Columns.PlaidItemID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(PlaidAccountLinks.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(PlaidAccountLinks.Columns.PlaidItemID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(PlaidAccountLinks.Columns.PlaidItemID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[uuid.UUID]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.PlaidAccountLinks = &count
	}

	return nil
}

type plaidItemJoins[Q dialect.Joinable] struct {
	typ               string
	PlaidAccountLinks modAs[Q, plaidAccountLinkColumns]
}

func (j plaidItemJoins[Q]) aliasedAs(alias string) plaidItemJoins[Q] {
	return buildPlaidItemJoins[Q](buildPlaidItemColumns(alias), j.typ)
}

func buildPlaidItemJoins[Q dialect.Joinable](cols plaidItemColumns, typ string) plaidItemJoins[Q] {
	return plaidItemJoins[Q]{
		typ: typ,
		PlaidAccountLinks: modAs[Q, plaidAccountLinkColumns]{
			c: PlaidAccountLinks.Columns,
			f: func(to plaidAccountLinkColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PlaidAccountLinks.NameExpr().As(to.Alias())).On(
						to.PlaidItemID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
